// The music the exercise builder writes with (exerciseBuilder.ts): chord types and their tones,
// the chord scales, and the lines through a progression (guide tones, chord tones and scales in
// eighth notes), all in C. The lick database's scripts use them too (scripts/lickExercises.ts).
//
// The arpeggio, interval and rhythm drills follow the exercise families of K. B. Kelly and
// E. Rasmussen, "A Guide to Exploring Jazz Improvisation - Book 1" (Maricopa Open Digital Press,
// 2023, CC BY 4.0), Module 1. The notes here are generated by this code, not copied.

import { chordTones, parseChord, type Chord } from '../../music/chords'
import type { ChordSpan, TimedNote } from './lickCharts'

/** A chord family: its chart suffix and its tones in semitones above the root. */
export interface ChordType {
  label: string
  suffix: string
  tones: number[]
}

export const TRIADS: Record<string, ChordType> = {
  major: { label: 'major', suffix: '', tones: [0, 4, 7] },
  minor: { label: 'minor', suffix: '-', tones: [0, 3, 7] },
  diminished: { label: 'diminished', suffix: 'o', tones: [0, 3, 6] },
  augmented: { label: 'augmented', suffix: '+', tones: [0, 4, 8] },
  sus4: { label: 'sus4', suffix: 'sus', tones: [0, 5, 7] },
}

// Seventh chords; the ninth (14) completes the 3-5-7-9 arpeggios
export const SEVENTHS: Record<string, ChordType> = {
  maj7: { label: 'major 7th', suffix: '^7', tones: [0, 4, 7, 11] },
  min7: { label: 'minor 7th', suffix: '-7', tones: [0, 3, 7, 10] },
  dom7: { label: 'dominant 7th', suffix: '7', tones: [0, 4, 7, 10] },
  half: { label: 'half-diminished', suffix: 'h7', tones: [0, 3, 6, 10] },
  dim7: { label: 'diminished 7th', suffix: 'o7', tones: [0, 3, 6, 9] },
  minMaj7: { label: 'minor-major 7th', suffix: '-^7', tones: [0, 3, 7, 11] },
}
export const NINTH = 14

/** A note of an arpeggio or scale: step `index` of `tones`, going on in the octaves above. */
export function stepOf(tones: number[], index: number): number {
  const octave = Math.floor(index / tones.length)
  return tones[((index % tones.length) + tones.length) % tones.length] + 12 * octave
}

/** Root pitches for a run of roots, each as close as possible to the last, kept between F3 and G4. */
export function rootPitches(roots: number[], first = 60): number[] {
  const out: number[] = []
  for (const pc of roots) {
    let pitch = nearest(pc, out.length ? out[out.length - 1] : first)
    if (pitch > 67) pitch -= 12
    if (pitch < 53) pitch += 12
    out.push(pitch)
  }
  return out
}

