/** The chord's tones as pitch classes (root, third, fifth, seventh), read with the app's chord rules. */
export function tonesOf(chord: Chord): number[] {
  return chordTones(chord).map((interval) => (chord.root + interval) % 12)
}

/** The scale a progression's chord is played with, as pitch classes. */
export function chordScale(chord: Chord): number[] {
  const t = chord.tensions
  const pick = (name: string) => SCALES.find((s) => s.name === name)!.steps
  const steps = (() => {
    switch (chord.quality) {
      case 'maj7': case 'maj6': case 'maj': return t.includes('#11') ? pick('Lydian') : pick('Ionian (major)')
      case 'min7': case 'min': return pick('Dorian')
      case 'min6': case 'minMaj7': return pick('Melodic minor')
      case 'half': return pick('Locrian #2') // the jazz scale of a half-diminished chord
      case 'dim7': case 'dim': return pick('Whole-half diminished')
      case 'dom7':
        if (t.includes('alt') || t.includes('#5') || t.includes('#9')) return pick('Altered')
        if (t.includes('b9')) return pick('Phrygian dominant')
        if (t.includes('#11')) return pick('Lydian dominant')
        return pick('Mixolydian')
      default: return pick('Mixolydian')
    }
  })()
  return steps.map((step) => (chord.root + step) % 12)
}

/**
 * The pitch of a pitch class nearest to a pitch (`direction` 0, the pitch itself included), or
 * the nearest one strictly above (`direction` 1) or below (`direction` -1).
 */
export function nearest(pc: number, to: number, direction = 0): number {
  const up = to + ((((pc - to) % 12) + 12) % 12) // at or above
  const down = up === to ? to : up - 12 // at or below
  if (direction > 0) return up === to ? to + 12 : up
  if (direction < 0) return down === to ? to - 12 : down
  return up - to <= to - down ? up : down
}

/** A chord span with its chord read. */
export type Change = { symbol: string; beats: number; chord: Chord }

export function readChanges(spans: ChordSpan[]): Change[] {
  return spans.map(([symbol, beats]) => {
    const chord = symbol ? parseChord(symbol) : null
    if (!symbol || !chord) throw new Error(`Progression chord ${symbol} cannot be read`)
    return { symbol, beats, chord }
  })
}

/**
 * A guide-tone line: one or two of each chord's guide tones (third and seventh), each as close as
 * possible to the note before, so the line moves by half steps, whole steps or common tones.
 */
export function guideToneLine(spans: ChordSpan[], perChord: 1 | 2, startOn: 'third' | 'seventh'): TimedNote[] {
  const notes: TimedNote[] = []
  let time = 0
  let last: number | null = null
  for (const { beats, chord } of readChanges(spans)) {
    const [, third, , seventh] = tonesOf(chord)
    const guides = [third, seventh]
    const first: number = last === null ? nearest(startOn === 'third' ? third : seventh, 66) : closestInRange(guides, last)
    if (perChord === 1 || beats < 2) {
      notes.push({ start: time, beats, pitch: first })
      last = first
    } else {
      const other = closestInRange(guides.filter((pc) => pc !== first % 12), first)
      notes.push({ start: time, beats: beats / 2, pitch: first }, { start: time + beats / 2, beats: beats / 2, pitch: other })
      last = other
    }
    time += beats
  }
  return notes
}

/**
 * The pitch of one of `pcs` closest to `from` within the range of a guide-tone line (G3 to G5),
 * the lower one on a tie: lines through all the keys stay in the range by jumping an octave.
 */
export function closestInRange(pcs: number[], from: number, low = 55, high = 79): number {
  const options = pcs.flatMap((pc) => [-12, 0, 12].map((octave) => nearest(pc, from) + octave)).filter((p) => p >= low && p <= high)
  return options.sort((a, b) => Math.abs(a - from) - Math.abs(b - from) || a - b)[0]
}

/**
 * A line of eighth notes through a progression on each chord's tones (`scale` false) or scale
 * (`scale` true): it goes on in one direction, turns at the edges of the range, and moves to the
 * nearest note of the next chord. The last chord gets one long note.
 */
export function eighthLine(spans: ChordSpan[], scale: boolean, low = 55, high = 81): TimedNote[] {
  const changes = readChanges(spans)
  const notes: TimedNote[] = []
  let time = 0
  let pitch: number | null = null
  let direction = 1
  changes.forEach(({ beats, chord }, index) => {
    const pcs = scale ? chordScale(chord) : tonesOf(chord)
    // The next note of the chord or scale in the line's direction, turning at the range's edges
    const step = (from: number) => {
      for (let tries = 0; tries < 2; tries++) {
        const next = direction > 0 ? Math.min(...pcs.map((pc) => nearest(pc, from, 1))) : Math.max(...pcs.map((pc) => nearest(pc, from, -1)))
        if (next >= low && next <= high) return next
        direction = -direction
      }
      return from
    }
    const last = index === changes.length - 1
    const count = last ? 1 : beats * 2
    for (let i = 0; i < count; i++) {
      if (pitch === null) pitch = nearest(chord.root, 60)
      else if (i > 0) pitch = step(pitch)
      else {
        // A new chord starts on its nearest tone, an octave away when that leaves the range
        const tone = chordToneNear(tonesOf(chord), pitch, direction)
        pitch = tone >= low && tone <= high ? tone : closestInRange(tonesOf(chord), pitch, low, high)
      }
      notes.push({ start: time + i * 0.5, beats: last ? beats : 0.5, pitch })
    }
    time += beats
  })
  return notes
}

/** The chord tone nearest to a pitch, a step on in the line's direction when there is one within a third. */
function chordToneNear(tones: number[], from: number, direction: number): number {
  const ahead = tones.map((pc) => nearest(pc, from, direction)).filter((p) => Math.abs(p - from) <= 4)
  if (ahead.length) return ahead.sort((a, b) => Math.abs(a - from) - Math.abs(b - from))[0]
  return tones.map((pc) => nearest(pc, from)).sort((a, b) => Math.abs(a - from) - Math.abs(b - from))[0]
}

/** A name with a capital first letter, except a Roman numeral (ii-V-I stays as it is). */
export const capital = (text: string) => (/^[iv]+[-\s]/.test(text) ? text : text[0].toUpperCase() + text.slice(1))

